package com.InnovaServe.core.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.UUID;
@Entity @Table(name="payment",schema="core")public class Payment extends TenantEntity{@Column(name="invoice_id",nullable=false)private UUID invoiceId;@Column(nullable=false,length=10)private String mode;@Column(nullable=false,precision=10,scale=2)private BigDecimal amount;@Column(length=100)private String reference;@Column(name="paid_at",insertable=false,updatable=false)private LocalDateTime paidAt;protected Payment(){}public Payment(UUID t,UUID invoice,String mode,BigDecimal amount,String reference){super(t);invoiceId=invoice;this.mode=mode;this.amount=amount;this.reference=reference;}public UUID getInvoiceId(){return invoiceId;}public BigDecimal getAmount(){return amount;}public String getMode(){return mode;}public String getReference(){return reference;}public LocalDateTime getPaidAt(){return paidAt;}}
